function showScreen(name){deskScreen=name;if(name!=='schedule')document.body.classList.remove('mobile-day-detail');document.querySelectorAll('.desk-screen').forEach(e=>e.classList.toggle('active',e.id==='screen-'+name));document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.screen===name));document.body.classList.toggle('chat-focus',name==='chat');$('screen-title').textContent=({schedule:'A clear week ahead.',people:'People make the plan.',requests:'Requests worth reviewing.',history:'Every dated change, kept.',sources:'Keep the original words.',handoff:'The next shift, informed.',settings:'Your coverage, your choice.',chat:'Talk with Sarah.'})[name];if(name==='history'&&!historyData)$('history-day').value=state.staffing?.selected_date||state.staffing?.selected_week||'';renderStaffing();}
