function readPages(title,text){const {body}=modal(title);const area=node('p'),pg=node('div',undefined,'pager');body.append(area,pg);const max=innerWidth<600?350:950;const pages=[];let rest=text;while(rest){let n=Math.min(max,rest.length);if(n<rest.length)n=Math.max(n-80,rest.lastIndexOf(' ',n));pages.push(rest.slice(0,n));rest=rest.slice(n).trimStart();}let index=0;function draw(){area.textContent=pages[index]||'';area.style.whiteSpace='pre-wrap';pager(pg,index,pages.length,n=>{index=n;draw();});}draw();}
let planningCenter=null,planningCleanup=null,planningHydrated=false;
function clearPlanningCenter(){if(planningCleanup){planningCleanup();planningCleanup=null;}planningCenter=null;document.body.classList.remove('mobile-day-detail');renderStaffing();}
function syncPlanningCenter(data){
 const team=data.state.current_production,week=data.state.staffing?.selected_week;
 if(planningCenter&&(planningCenter.team!==team||planningCenter.week!==week)){if(planningCleanup)planningCleanup();planningCleanup=null;planningCenter=null;}
 if(planningHydrated&&planningCenter?.type!=='running')return;planningHydrated=true;
 const message=data.state.assistant?.messages?.at(-1);if((!message?.planning_job_id&&!message?.planning_proposal_id)||message.planning_week!==week)return;
 const job=data.jobs.find(x=>x.id===message.planning_job_id);
 const proposal=data.state.staffing?.proposals?.find(x=>x.id===message.planning_proposal_id);
 if(proposal&&!proposal.accepted_at)planningCenter={type:'proposal',team,week,proposalId:proposal.id};
 else if(job?.status==='running')planningCenter={type:'running',team,week,jobId:job.id,request:message.planning_request,message:'The existing planning request is still running. Refresh to see its saved result; no new request was started.'};
 else if(job?.status==='error')planningCenter={type:'clarification',team,week,result:{answer:job.error||message.text||'This request could not finish. Review the saved week before asking again.',request:message.planning_request}};
 else if(job?.status==='complete')planningCenter={type:'clarification',team,week,result:{...job.result,answer:job.result?.answer||message.text||'The saved request is complete. Review the current week.',request:job.result?.request||message.planning_request}};
 else if(message.planning_status==='running')planningCenter={type:'clarification',team,week,result:{answer:'The app restarted before this conversation recorded a completed result. Check the saved proposals before sending another request.',request:message.planning_request}};
}
function showPlanningReply(reply){
 const team=state.current_production,week=state.staffing.selected_week;
 planningCenter={type:'clarification',team,week,result:{kind:reply.kind,answer:reply.answer,request:reply.staffing_request?.request||reply.request,facts:reply.facts||[]}};showScreen('schedule');
}
function renderPlanningCenter(wrap){
 if(planningCleanup){planningCleanup();planningCleanup=null;}
 const view=planningCenter;wrap.replaceChildren();document.body.classList.add('mobile-day-detail');
 if(view.type==='proposal'){
  const proposal=state.staffing.proposals.find(p=>p.id===view.proposalId);
  if(proposal&&!proposal.accepted_at&&state.staffing.proposals.filter(p=>p.kind==='week'&&p.week_start===view.week).at(-1)?.id===proposal.id){reviewProposal(proposal,true);return;}
  view.type='clarification';view.result={answer:'This proposal was accepted or changed. Review the saved dates or the current proposal before making another change.'};
 }
 const heading=node('div',undefined,'detail-heading');heading.append(node('h3',view.type==='running'?'Sarah is planning the week':'Planning request'),btt('Back to week',clearPlanningCenter));wrap.append(heading);
 const body=node('div',undefined,'dialog-body');body.dataset.planningState=view.type;wrap.append(body);
 const message=node('p',view.type==='running'?view.message:view.result.answer);message.setAttribute('role','status');body.append(message);
 const request=view.request||view.result?.request;
 if(request)body.append(btt('Read your request',()=>readPages('Your unchanged request',request)));
 if(view.type==='running'){body.setAttribute('aria-busy','true');return;}
 for(const fact of view.result.facts||[])body.append(btt(fact.length>90?fact.slice(0,85)+'…':fact,()=>readPages('Saved availability',fact)));
 if(request)body.append(btt('Edit in conversation',()=>{$('chat-message').value=request;showScreen('chat');$('chat-message').focus();},'primary'));
 if(view.result.kind==='needs_employees')body.append(btt('Add or import employees',()=>showScreen('people'),'primary'));
 else if(view.result.kind==='needs_hours')body.append(btt('Review customer hours',()=>showScreen('settings'),'primary'));
 else if(view.result.facts?.length)body.append(btt('Edit availability',()=>showScreen('people')));
 body.append(btt('Review saved week',clearPlanningCenter));
}
async function watchChatPlanning(answer,team,week){
 if(state.current_production!==team||state.staffing.selected_week!==week)throw Error('The team/week changed. Reopen that conversation to review its request.');
 let job=answer.job;planningCenter={type:'running',team,week,jobId:job.id,request:answer.staffing_request.request,message:'Reading the saved team and selected week…'};showScreen('schedule');busy=true;
 try{
  for(;;){
   const data=await refresh();if(data.state.current_production!==team||data.state.staffing.selected_week!==week)throw Error('The team/week changed. This request remains attached to its original conversation.');
   job=data.jobs.find(x=>x.id===job.id);if(!job)throw Error('The app restarted. Check saved proposals before sending another request.');
   if(job.status==='error'){showPlanningReply({answer:job.error,request:answer.staffing_request.request});break;}
   if(job.status==='complete'){
    if(job.result.proposal){planningCenter={type:'proposal',team,week,proposalId:job.result.proposal.id};showScreen('schedule');}
    else showPlanningReply(job.result);
    status();break;
   }
   if(planningCenter?.jobId===job.id){planningCenter.message=job.trace.at(-1)?.detail||'Sarah is checking this team’s saved data…';renderStaffing();}
   await new Promise(resolve=>setTimeout(resolve,500));
  }
 }finally{busy=false;}
}

