function calcCoverage(plan){if(!plan)return null;const bounds=new Set([plan.open,plan.close]);for(const w of plan.coverage_windows||[])for(const t of [w.start,w.end])bounds.add(t);for(const s of plan.shifts){for(const t of [s.start,s.end,...s.breaks.flatMap(b=>[b.start,b.end])])if(t>plan.open&&t<plan.close)bounds.add(t);}const a=[...bounds].sort((x,y)=>x-y),requirements=plan.role_requirements||{Team:plan.minimum};let missing=0;const segments=a.slice(0,-1).map((start,i)=>{const end=a[i+1],active=plan.shifts.filter(s=>s.start<=start&&s.end>=end&&!s.breaks.some(b=>b.start<end&&b.end>start));const count=new Set(active.map(s=>s.employee_id||s.employee)).size,role_missing={};for(const [role,needed] of Object.entries(requirements)){const n=new Set(active.filter(s=>role==='Team'||s.role===role).map(s=>s.employee_id||s.employee)).size;const required=!plan.coverage_windows||plan.coverage_windows.some(w=>w.start<=start&&w.end>=end);role_missing[role]=required?Math.max(0,needed-n):0;}missing+=(end-start)*Object.values(role_missing).reduce((x,y)=>x+y,0);return {start,end,count,role_missing,missing:Math.max(0,plan.minimum-count)};});return {segments,role_missing_person_minutes:missing,scheduled_work_minutes:plan.shifts.reduce((sum,s)=>sum+s.end-s.start-s.breaks.reduce((n,b)=>n+b.end-b.start,0),0)};}
function renderMetrics(){const f=state.staffing;if(!f)return;const ds=displayedDays(),plans=ds.filter(d=>d.plan),minutes=plans.reduce((n,d)=>n+(d.coverage?.scheduled_work_minutes||0),0),gaps=plans.reduce((n,d)=>n+(d.coverage?.role_missing_person_minutes||0),0),saved=f.days.filter(d=>d.plan).length;const data=[['Employees',f.employees.length],['Planned hours',hours(minutes)],['Role-hours missing',hours(gaps)],['Saved dates',saved+'/7']];$('project-progress').replaceChildren();for(const [label,value] of data){const card=node('div',undefined,'progress-stage');card.append(node('span',label==='Role-hours missing'&&gaps?'!':'◈','progress-icon'),node('strong',String(value)),node('span',label));$('project-progress').append(card);}}
