function openWeekPlanning(previous=''){
 const {d,body}=modal('Plan this team’s week');
 body.append(node('p','Saved team · '+fmtDate(state.staffing.selected_week,true)+'. Proposals need your review before they replace saved dates.'));
 body.append(btt('Suggest with current restrictions',async()=>{const p=await api('staff/suggest',{week_start:state.staffing.selected_week});d.close();previewId=p.id;await refresh();reviewProposal(p);},'primary'));
 if(!runtimeInfo.optional_strands_available){body.append(node('p','AI planning is unavailable in this edition. The saved-availability planner works here.','muted'));return;}
 const label=node('label','What should Sarah plan?'),request=node('textarea');request.rows=2;request.maxLength=1500;request.value=previous;request.placeholder='Cap Bo at 12 hours this week';request.setAttribute('aria-label','Planning request');label.append(request);body.append(label);
 body.append(btt('Plan with Sarah · local AI',async()=>{if(!request.value.trim())throw Error('Enter a request, or say Plan the selected week.');d.close();await planWeekWithSarah(request.value.trim());}));
 body.append(node('p','Follow-ups retain this week’s unaccepted exclusions and replace only the named person’s cap. To reset, say: Start a fresh plan for the selected week. Unclear removals need clarification.','muted'));
}
async function planWeekWithSarah(request){
 const team=state.current_production,week=state.staffing.selected_week;
 const {d,body}=modal('Sarah is planning the week'),message=node('p','Reading the saved team and selected week…');
 body.append(message);let open=true;d.addEventListener('close',()=>{open=false;});busy=true;
 try{
  let job=await api('staff/agent-plan',{production_id:team,week_start:week,request});
  for(;;){
   await new Promise(resolve=>setTimeout(resolve,750));const current=await api('state');
   if(current.state.current_production!==team)throw Error('The selected team changed. Reopen its saved proposal to review it.');
   job=current.jobs.find(row=>row.id===job.id);
   if(!job)throw Error('The app restarted. Check saved proposals before starting another request.');
   message.textContent=job.trace.at(-1)?.detail||'Sarah is reading this team’s saved data…';
   if(job.status==='error')throw Error(job.error);
   if(job.status==='complete'){
    await refresh();status(job.result.answer);
    if(open){d.close();if(job.result.proposal){previewId=job.result.proposal.id;reviewProposal(job.result.proposal);}else{const result=job.result,view=modal(result.kind==='constraint_clarification'?'Clarify this request':'Before planning');view.body.append(node('p',result.answer));if(result.request)view.body.append(btt('Read your request',()=>readPages('Your unchanged request',result.request)));for(const fact of result.facts||[])view.body.append(btt(fact.length>95?fact.slice(0,90)+'…':fact,()=>readPages('Saved availability',fact)));if(result.kind==='constraint_clarification')view.body.append(btt('Edit request',()=>{view.d.close();openWeekPlanning(request);},'primary'));view.body.append(btt(result.kind==='needs_hours'?'Review customer hours':result.kind==='needs_employees'?'Add or import employees':'Edit availability',()=>{view.d.close();showScreen(result.kind==='needs_hours'?'settings':'people');}));}}
    break;
   }
  }
 }finally{busy=false;if(open)d.close();}
}
