function reviewWeekInCenter(p){
 const wrap=$('schedule-detail'), report=p.payload, view=planningCenter;
 const days=report.days, selected=days.findIndex(day=>day.date===view?.visualDay);
 let dayIndex=selected>=0?selected:Math.max(0,days.findIndex(day=>day.shifts.length));
 let tab=view?.visualTab==='request'?'request':'week';
 const team=state.current_production;
 const current=()=>planningCenter===view&&state.current_production===team&&state.staffing.selected_week===p.week_start;
 const total=report.hours.reduce((sum,row)=>sum+row.minutes,0);
 const missing=days.reduce((sum,day)=>sum+calcCoverage(day).role_missing_person_minutes,0);
 const setTab=next=>{tab=next;if(view)view.visualTab=next;draw();};
 function draw(){
  wrap.replaceChildren();
  const heading=node('div',undefined,'detail-heading');
  heading.append(node('h3','Your proposed week'),btt('Back to week',clearPlanningCenter));
  const body=node('div',undefined,'proposal-visual');body.dataset.planningState='proposal';body.dataset.proposalId=p.id;
  wrap.append(heading,body);
  const summary=node('div',undefined,'proposal-summary');
  summary.append(node('span','PROPOSAL · '+fmtDate(p.week_start,true),'proposal-kicker'),node('strong',hours(total)+' planned hours'),node('span',hours(missing)+' role-hours uncovered',missing?'proposal-gap':'proposal-covered'));
  body.append(summary);
  const tabs=node('div',undefined,'proposal-tabs');
  for(const [value,label] of [['week','Week & shifts'],['request','Request & changes']]){
   const b=btt(label,()=>setTab(value),tab===value?'primary':'quiet');b.setAttribute('aria-pressed',String(tab===value));tabs.append(b);
  }
  body.append(tabs);
  const canvas=node('div',undefined,'proposal-canvas');canvas.tabIndex=0;canvas.setAttribute('role','region');canvas.setAttribute('aria-label',tab==='week'?'Proposed shifts':'Request and schedule changes');body.append(canvas);
  if(tab==='week'){
   const strip=node('div',undefined,'proposal-days');strip.setAttribute('aria-label','Choose a proposed date');
   days.forEach((day,index)=>{
    const coverage=calcCoverage(day),minutes=day.shifts.reduce((sum,s)=>sum+s.end-s.start,0),date=new Date(day.date+'T12:00:00');
    const b=btt('',()=>{dayIndex=index;if(view)view.visualDay=day.date;draw();},'proposal-day'+(dayIndex===index?' active':''));
    b.setAttribute('aria-label',fmtDate(day.date)+', '+hours(minutes)+' proposed hours');b.setAttribute('aria-pressed',String(dayIndex===index));b.dataset.proposalDate=day.date;
    b.append(node('span',date.toLocaleDateString('en-US',{weekday:'short'})),node('strong',String(date.getDate())),node('small',hours(minutes)+'h'));
    if(coverage.role_missing_person_minutes)b.classList.add('has-gap');strip.append(b);
   });
   canvas.append(strip);
   const day=days[dayIndex],coverage=calcCoverage(day),title=node('div',undefined,'proposal-date-heading');
   title.append(node('h3',fmtDate(day.date)),node('span',day.shifts.length+' '+(day.shifts.length===1?'shift':'shifts')));canvas.append(title);
   if(!day.shifts.length){
    const closed=day.operating_hours?.closed;
    canvas.append(node('p',closed?'Closed · no shifts proposed.':'No shifts proposed for this date. Review saved availability and the uncovered hours.','proposal-no-shifts'));
   }else{
    const grid=node('div',undefined,'proposal-shifts');
    const from=Math.min(...day.shifts.map(s=>s.start)),to=Math.max(...day.shifts.map(s=>s.end)),span=Math.max(15,to-from);
    for(const shift of day.shifts){
     const saved=state.staffing.employees.find(e=>e.id===shift.employee_id),name=saved?.name||shift.employee||'Employee name not supplied';
     const card=node('article',undefined,'proposal-shift');card.dataset.employeeId=shift.employee_id;card.dataset.shiftStart=shift.start;card.dataset.shiftEnd=shift.end;
     const head=node('div',undefined,'proposal-shift-head'),avatar=node('span',name.split(/\s+/).map(s=>s[0]).slice(0,2).join(''),'proposal-person-mark'),label=node('div');avatar.setAttribute('aria-hidden','true');
     label.append(node('strong',name),node('small',shift.role||'Role not supplied'));head.append(avatar,label,node('b',hours(shift.end-shift.start)+'h'));
     const range=node('p',ampm(shift.start)+' – '+ampm(shift.end),'proposal-shift-time');
     const track=node('div',undefined,'proposal-shift-track'),bar=node('span');track.setAttribute('aria-hidden','true');bar.style.marginLeft=((shift.start-from)/span*100)+'%';bar.style.width=((shift.end-shift.start)/span*100)+'%';track.append(bar);
     card.append(head,range,track);grid.append(card);
    }
    canvas.append(grid,node('p','Timeline: '+ampm(from)+' – '+ampm(to)+'. Shift lengths shown before unassigned lunch breaks.','proposal-axis'));
   }
   if(coverage.role_missing_person_minutes)canvas.append(node('p',hours(coverage.role_missing_person_minutes)+' role-hours still uncovered on this date.','proposal-day-gap'));
  }else{
   const policy=report.constraints;
   const section=(title,lines)=>{const block=node('section',undefined,'proposal-facts');block.append(node('h3',title));for(const line of lines)block.append(node('p',line));canvas.append(block);};
   if(policy){section('Your exact words',(policy.request_history||[{request:policy.request}]).map((x,i)=>'Request '+(i+1)+': '+x.request));section('Restrictions in this proposal',policy.constraints.map(x=>x.label));}
   section('Changes from the saved schedule',report.changes_from_saved?.length?report.changes_from_saved.map(x=>x.label):['No shift changes from the saved schedule.']);
   if(policy)section('Effect on the automatic suggestion',report.changes_from_automatic?.length?report.changes_from_automatic.map(x=>x.label):['No shift changes from the automatic suggestion.']);
   const gaps=[...report.unknown_availability.map(x=>x.employee+': availability not provided '+x.date),...report.time_off.map(x=>x.employee+': time off '+x.date+' — '+x.reason)];if(gaps.length)section('Availability to review',gaps);
   section('Employee totals',report.hours.filter(x=>x.minutes||x.preferences).map(x=>x.name+': '+hours(x.minutes)+' proposed hours; '+hours(x.projected_overtime_minutes)+' over weekly threshold.'+(x.preferences?' Preference: '+x.preferences:'')));
  }
  const footer=node('div',undefined,'proposal-footer');footer.append(node('p','Accept saves all seven proposed dates and keeps earlier revisions. Lunch is not assigned.'));
  const actions=node('div',undefined,'proposal-actions');
  actions.append(btt('Edit shifts',()=>{clearPlanningCenter();editWeek(p);}),btt('Accept reviewed week',async()=>{
   if(!current())throw Error('The team or week changed. Reopen the current proposal before accepting.');
   await api('staff/accept',{id:p.id,sha256:p.sha256});previewId=null;clearPlanningCenter();await refresh();status('Saved all seven dates. Earlier revisions remain in History.');
  },'primary'));footer.append(actions);body.append(footer);
 }
 draw();
}
